def countInRange(nums, lo, hi):
    n = len(nums)
    a, b = 0, n - 1
    start = None
    while a < b:
        mid = (a + b) // 2
        if nums[mid] > nums[b]:
            a = mid + 1
        elif nums[mid] < nums[b]:
            b = mid
        else:
            if nums[b - 1] > nums[b]:
                start = b
                break
            b -= 1
    if start is None:
        start = a

    def first_at_least(v):
        l, r = 0, n
        while l < r:
            m = (l + r) // 2
            if nums[(start + m) % n] < v:
                l = m + 1
            else:
                r = m
        return l

    return first_at_least(hi + 1) - first_at_least(lo)
